import{_ as r,a0 as o,w as p,s as g,I as l,x as e,a1 as a,A as s,ao as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"Linux 系统实时监控的瑞士军刀 —— Glances | LCTT x X-CMD","titleTemplate":false,"description":"Linux 系统实时监控的瑞士军刀 —— Glances | LCTT (201403) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 系统实时监控的瑞士军刀 —— Glances | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 系统实时监控的瑞士军刀 —— Glances | LCTT (201403) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201403/Glances – An Advanced Real Time System Monitoring Tool for Linux","title":"Linux 系统实时监控的瑞士军刀 —— Glances","tag":"201403","desc":""},"relativePath":"201403/Glances – An Advanced Real Time System Monitoring Tool for Linux.md","filePath":"[post].md"}'),d={name:"201403/Glances – An Advanced Real Time System Monitoring Tool for Linux.md"};function u(c,n,m,x,f,G){const t=o("Link");return p(),g("div",null,[n[25]||(n[25]=l("h1",{id:"linux-系统实时监控的瑞士军刀-——-glances",tabindex:"-1"},[e("Linux 系统实时监控的瑞士军刀 —— Glances "),l("a",{class:"header-anchor",href:"#linux-系统实时监控的瑞士军刀-——-glances","aria-label":"Permalink to “Linux 系统实时监控的瑞士军刀 —— Glances”"},"​")],-1)),l("p",null,[n[1]||(n[1]=e("早些时候，我们提到过有很多可以用来监视系统性能的 Linux ",-1)),a(t,{href:"http://www.tecmint.com/command-line-tools-to-monitor-linux-performance/"},{default:s(()=>[...n[0]||(n[0]=[e("系统监视工具",-1)])]),_:1}),n[2]||(n[2]=e("。 但我们估计，或许更多的用户会倾向与绝大多数 Linux 发行版都带的工具 （",-1)),n[3]||(n[3]=l("strong",null,"top",-1)),n[4]||(n[4]=e(" 命令）。",-1))]),l("p",null,[a(t,{href:"http://www.tecmint.com/12-top-command-examples-in-linux/"},{default:s(()=>[...n[5]||(n[5]=[e("top 命令",-1)])]),_:1}),n[6]||(n[6]=e("是 Linux 下的一个实时任务管理器， 同时也是用于在 ",-1)),n[7]||(n[7]=l("strong",null,"GNU/Linux",-1)),n[8]||(n[8]=e(" 发行版中寻找系统性能方面的瓶颈，并帮助我们作出正确操作的常用系统监视工具。 她有着一个极为简洁的界面，并自带少量的可以帮助我们快速了解系统性能的实用选项。",-1))]),n[26]||(n[26]=i('<p>但是，有些时候想要通过她寻找一个占用系统资源比较大的应用或进程可能会比较困难。 因为 top 命令本身并不会帮助我们高亮那些吃太多 <strong>CPU</strong>，<strong>内存</strong>，或者其他资源的程序。</p><p>为了达到这个目标，这里我们将介绍一款超牛逼的系统监视程序 —— <strong>Glances</strong>。 她可以自动高亮利用最高系统资源的程序，并为 Linux/Unix 服务器提供尽可能多的信息。</p><h3 id="什么是-glances" tabindex="-1">什么是 Glances？ <a class="header-anchor" href="#什么是-glances" aria-label="Permalink to “什么是 Glances？”">​</a></h3><p><strong>Glances</strong> 是一个由 Python 编写，使用 <strong>psutil</strong> 库来从系统抓取信息的基于 curses 开发的跨平台命令行系统监视工具。 通过 Glances，我们可以监视 <strong>CPU，平均负载，内存，网络流量，磁盘 I/O，其他处理器</strong> 和 <strong>文件系统</strong> 空间的利用情况。</p><p>Glances 是一个用来监视 <strong>GNU/Linux</strong> 和 <strong>FreeBSD</strong> 操作系统的 <strong>GPL</strong> 授权的自由软件。</p><p>Glances 同时也提供了很多实用的选项。 其中我们能够在配置文件见到的一项主要的功能就是设置关键值及相应的标签 （<strong>careful[小心]</strong>, <strong>warning[警告]</strong> 和 <strong>critical[严重]</strong>）， 然后她会自动帮我们用不同颜色标出系统达到某个瓶颈的信息。</p><h3 id="glances-主要功能" tabindex="-1">Glances 主要功能 <a class="header-anchor" href="#glances-主要功能" aria-label="Permalink to “Glances 主要功能”">​</a></h3><ul><li>CPU 信息 （用户的相关应用, 系统核心程序和空闲程序）</li><li>总内存信息，包括了物理内存，交换空间和空闲内存等等</li><li>之前的 1 分钟、5 分钟和 15 分钟平均的 CPU 负载</li><li>网络链接的下行和上行速度</li><li>处理器总数，以及其活动状态</li><li>硬盘 I/O 相关（读写）速度详情</li><li>当前挂载设备的磁盘使用情况</li><li>高 CPU 和内存使用的进程名，和相关应用的位置</li><li>在底部显示当前日期和时间</li><li>将消耗最高系统资源的进程用红色标出</li></ul><p>下面是一个 Glances 的使用截图：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/02/Glances-Monitoring.jpeg" alt="Glances View"></p><h3 id="在-linux-unix-系统中安装-glances" tabindex="-1">在 Linux/Unix 系统中安装 Glances <a class="header-anchor" href="#在-linux-unix-系统中安装-glances" aria-label="Permalink to “在 Linux/Unix 系统中安装 Glances”">​</a></h3>',11)),l("p",null,[n[10]||(n[10]=e("虽然这个工具的发布比较晚，但你仍然可以在 ",-1)),n[11]||(n[11]=l("strong",null,"Red Hat",-1)),n[12]||(n[12]=e(" 系的系统中通过 ",-1)),a(t,{href:"http://www.tecmint.com/how-to-enable-epel-repository-for-rhel-centos-6-5/"},{default:s(()=>[...n[9]||(n[9]=[e("EPEL 软件源",-1)])]),_:1}),n[13]||(n[13]=e("安装。在终端用下面的命令安装：",-1))]),n[27]||(n[27]=i(`<h4 id="对于-rhel-centos-fedora-发行版" tabindex="-1">对于 RHEL/CentOS/Fedora 发行版 <a class="header-anchor" href="#对于-rhel-centos-fedora-发行版" aria-label="Permalink to “对于 RHEL/CentOS/Fedora 发行版”">​</a></h4><pre><code># yum install -y glances
</code></pre><h4 id="对于-debian-ubuntu-linux-mint-发行版" tabindex="-1">对于 Debian/Ubuntu/Linux Mint 发行版 <a class="header-anchor" href="#对于-debian-ubuntu-linux-mint-发行版" aria-label="Permalink to “对于 Debian/Ubuntu/Linux Mint 发行版”">​</a></h4><pre><code>$ sudo apt-add-repository ppa:arnaud-hartmann/glances-stable
$ sudo apt-get update
$ sudo apt-get install glances
</code></pre><h3 id="如何使用-glances" tabindex="-1">如何使用 Glances <a class="header-anchor" href="#如何使用-glances" aria-label="Permalink to “如何使用 Glances”">​</a></h3><p>首先，你需要在终端中输入以下命令</p><pre><code># glances
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/02/Glances-Screen.jpeg" alt="Glances Preview – Ubuntu 13.10"></p><p>按下 ‘<strong>q</strong>‘ （‘<strong>ESC</strong>‘ 和 ‘<strong>Ctrl-C</strong>‘ 也可以） 退出 Glances 终端。 这里是从 <strong>CentOS 6.5</strong> 截取的另一张截图：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/02/Glances-Screen-Centos.jpeg" alt="Glances Preview – CentOS 6.5"></p><p>Glances 的默认刷新频率是 <strong>1</strong> （秒），但是你可以通过在终端指定参数来手动定义其刷新频率</p><pre><code># glances -t 2
</code></pre><h3 id="glances-中颜色的含义" tabindex="-1">Glances 中颜色的含义 <a class="header-anchor" href="#glances-中颜色的含义" aria-label="Permalink to “Glances 中颜色的含义”">​</a></h3><p>Glances 会用一下几种颜色来代表状态：</p><ul><li>绿色：OK（一切正常）</li><li>蓝色：CAREFUL（需要注意）</li><li>紫色：WARNING（警告）</li><li>红色：CRITICAL（严重）</li></ul><p>阀值可以在配置文件中设置，一般阀值被默认设置为（<strong>careful=50</strong>、<strong>warning=70</strong>、<strong>critical=90</strong>）。</p><p>我们可以按照自己的需求在配置文件（默认在 <strong>/etc/glances/glances.conf</strong>）中自定义。</p><h3 id="glances-的选项" tabindex="-1">Glances 的选项 <a class="header-anchor" href="#glances-的选项" aria-label="Permalink to “Glances 的选项”">​</a></h3><p>除了很多命令行选项之外，Glances 还提供了更多的可在其运行时开关输出信息选项的<strong>快捷键</strong>，下面是一些例子：</p><ul><li>a – 对进程自动排序</li><li>c – 按 CPU 百分比对进程排序</li><li>m – 按内存百分比对进程排序</li><li>p – 按进程名字母顺序对进程排序</li><li>i – 按读写频率（I/O）对进程排序</li><li>d – 显示/隐藏磁盘 I/O 统计信息</li><li>f – 显示/隐藏文件系统统计信息</li><li>n – 显示/隐藏网络接口统计信息</li><li>s – 显示/隐藏传感器统计信息</li><li>y – 显示/隐藏硬盘温度统计信息</li><li>l – 显示/隐藏日志（log）</li><li>b – 切换网络 I/O 单位（Bytes/bits）</li><li>w – 删除警告日志</li><li>x – 删除警告和严重日志</li><li>1 – 切换全局 CPU 使用情况和每个 CPU 的使用情况</li><li>h – 显示/隐藏这个帮助画面</li><li>t – 以组合形式浏览网络 I/O</li><li>u – 以累计形式浏览网络 I/O</li><li>q – 退出（‘<strong>ESC</strong>‘ 和 ‘<strong>Ctrl&amp;C</strong>‘ 也可以）</li></ul><h3 id="远程使用-glances" tabindex="-1">远程使用 Glances <a class="header-anchor" href="#远程使用-glances" aria-label="Permalink to “远程使用 Glances”">​</a></h3><p>你甚至也可以通过 Glances 来监视远程系统。 要在远程系统使用 ‘<strong>glances</strong>’，需要在服务器运行 ‘<strong>glances -s</strong>’（-s 启动服务器/客户端模式）命令。</p><pre><code># glances -s

Define the password for the Glances server
Password: 
Password (confirm): 
Glances server is running on 0.0.0.0:61209
</code></pre><p><strong>注意</strong>：当你执行了‘<strong>glances</strong>’命令后，她会让你为 Glances 服务器设置密码。</p><p>当你设置完毕，你将看到 “Glances server is running on 0.0.0.0:61209” （Glances 服务器正在 0.0.0.0 的 61209 端口运行）的消息。</p><p>当 Glances 服务器启动后，到本地执行下面的命令来指定服务器IP地址或主机名以链接。</p><p>注：这里的 ‘<strong>172.16.27.56</strong>’ 是我 Glances 服务器的 IP 地址。</p><pre><code># glances -c -P 172.16.27.56
</code></pre><p>下面是一些在使用服务器/客户端模式时必须知道的事情：</p><pre><code>* 在服务器模式，你可以通过 \`-B 地址\` 来设置绑定地址，也可以通过 \`-p 端口\` 来绑定监听的 TCP 端口
* 在客户端模式，你可以通过同样的 \`-p 端口\` 来指定服务器端口
* 默认的绑定地址是 0.0.0.0，但这么做会监听所有网络接口的指定端口
* 在服务器/客户端模式下，限制的阀值将由服务器的设置决定
* 你也可以在命令行下用过 \`-P 密码\` 的方式来为服务器端设置一个密码
</code></pre><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p><strong>Glances</strong> 对于大多用户而言是个在系统资源上提供过多信息的工具。但是如果你是一个想要仅从命令行就能快速获取系统整体状况的系统管理员，那这个工具绝对是你的必备利器。</p><h3 id="译者注" tabindex="-1">译者注 <a class="header-anchor" href="#译者注" aria-label="Permalink to “译者注”">​</a></h3><ol><li>请不要将 glances（本文中的工具）和 glance（一个 OpenStack 的工具）这两个包搞混了</li><li>Ubuntu 官方 Extra 源中的 glances 因为 python 库移动的问题导致无法正常使用 但可以通过建立软链接的方式临时修复：sudo ln -s /usr/lib/python2.7/dist-packages/glances /usr/share/pyshared/glances</li></ol><hr>`,35)),l("p",null,[n[15]||(n[15]=e("via: ",-1)),a(t,{href:"http://www.tecmint.com/glances-an-advanced-real-time-system-monitoring-tool-for-linux/"},{default:s(()=>[...n[14]||(n[14]=[e("http://www.tecmint.com/glances-an-advanced-real-time-system-monitoring-tool-for-linux/",-1)])]),_:1})]),l("p",null,[n[18]||(n[18]=e("译者：",-1)),a(t,{href:"https://github.com/vizv"},{default:s(()=>[...n[16]||(n[16]=[e("VizV",-1)])]),_:1}),n[19]||(n[19]=e(" 校对：",-1)),a(t,{href:"https://github.com/wxy"},{default:s(()=>[...n[17]||(n[17]=[e("wxy",-1)])]),_:1})]),l("p",null,[n[22]||(n[22]=e("本文由 ",-1)),a(t,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...n[20]||(n[20]=[e("LCTT",-1)])]),_:1}),n[23]||(n[23]=e(" 原创翻译，",-1)),a(t,{href:"http://linux.cn/"},{default:s(()=>[...n[21]||(n[21]=[e("Linux中国",-1)])]),_:1}),n[24]||(n[24]=e(" 荣誉推出",-1))])])}const C=r(d,[["render",u]]);export{w as __pageData,C as default};
